//! Dynamic dispatch for selectors that several game classes implement: `[receiver sel]`
//! where the receiver's exact class is not known statically (generated by
//! `tools/port/gen_send.py`; re-run it after changing one of these signatures).
//!
//! Each function walks the receiver's class chain to the nearest implementation. A nil
//! receiver returns the zero value, like ObjC; so does a class that does not respond.

#![allow(clippy::too_many_arguments)]

use crate::prelude::*;

/// `[receiver activate]`
pub fn activate(world: &mut World, receiver: Option<Entity>) {
    let Some(receiver) = receiver else {
        return ();
    };
    let mut class = try_isa(world, receiver);
    while let Some(current) = class {
        match current.name {
            "AdBlockerLogic" => return crate::logic::idol_ui_widgets::ad_blocker_logic::activate(world, receiver),
            "AnchorLogic" => return crate::logic::underwater_baitmaster_laser::anchor_logic::activate(world, receiver),
            "ApocalypseGemLogic" => return crate::logic::apocalypse_temples::apocalypse_gem_logic::activate(world, receiver),
            "ChainSpearLogic" => return crate::logic::underwater_stage::chain_spear_logic::activate(world, receiver),
            "ChumBucketLogic" => return crate::logic::underwater_baitmaster_laser::chum_bucket_logic::activate(world, receiver),
            "HealthBarLogic" => return crate::logic::ice_island::health_bar_logic::activate(world, receiver),
            "KonkeyDongLadderLogic" => return crate::logic::konkeydong::konkey_dong_ladder_logic::activate(world, receiver),
            "KonkeyDongPlatformLogic" => return crate::logic::konkeydong::konkey_dong_platform_logic::activate(world, receiver),
            "MapPaperLogic" => return crate::logic::idol_ui_widgets::map_paper_logic::activate(world, receiver),
            "NoPeeClamLogic" => return crate::logic::nopee::no_pee_clam_logic::activate(world, receiver),
            "NoPeeFishLogic" => return crate::logic::nopee::no_pee_fish_logic::activate(world, receiver),
            "NoPeeMineLogic" => return crate::logic::nopee::no_pee_mine_logic::activate(world, receiver),
            "NoPeeObjectLogic" => return crate::logic::nopee::no_pee_object_logic::activate(world, receiver),
            "NoPeeParticleLogic" => return crate::logic::nopee::no_pee_particle_logic::activate(world, receiver),
            "NoPeeSeaBlobLogic" => return crate::logic::nopee::no_pee_sea_blob_logic::activate(world, receiver),
            "NoPeeTreasureLogic" => return crate::logic::nopee::no_pee_treasure_logic::activate(world, receiver),
            "SpearLogic" => return crate::logic::island_objects::spear_logic::activate(world, receiver),
            "TheRunsPlatformLogic" => return crate::logic::theruns::the_runs_platform_logic::activate(world, receiver),
            "TileDrainLogic" => return crate::logic::underwater_paindrain::tile_drain_logic::activate(world, receiver),
            "UnderwaterTempleLogic" => return crate::logic::underwater_stage::underwater_temple_logic::activate(world, receiver),
            _ => class = current.superclass,
        }
    }
}

