/// `-[NSObject respondsToSelector:]`
pub fn responds_to(world: &World, receiver: Option<Entity>, selector: &str) -> bool {
    let Some(receiver) = receiver else {
        return false;
    };
    let mut class = try_isa(world, receiver);
    while let Some(current) = class {
        let own = SELECTORS.iter().find(|(name, _)| *name == current.name);
        if let Some((_, selectors)) = own {
            if selectors.contains(&selector) {
                return true;
            }
        }
        class = current.superclass;
    }
    false
}
